pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }
    function testFuzz_property(uint256 amount, address from, address to) public {
        vm.assume(to != address(0));
        amount = bound(amount, 0, type(uint128).max);
        address[] memory tos = new address[](1);
        tos[0] = to;
        Recorder rec = new Recorder();
        bool ok;
        try c.transfer(from, address(rec), tos, amount) { ok = true; } catch { ok = false; }
        assertTrue(ok && rec.amount() == amount);
    }
}

contract Recorder {
    uint256 public amount;
    function transferFrom(address, address, uint256 v) external {
        amount = v;
    }
}
